/** 
 * Returns the specified resource bundle, which is a properties file that aids in localization of skins. This method is handy since it uses the class loader that other Jive classes are loaded from (hence, it can load bundles that are stored in jive.jar).
 * @param baseName the name of the resource bundle to load.
 * @param locale the desired Locale.
 * @return the specified resource bundle, if it exists.
 */
public static ResourceBundle getResourceBundle(String baseName, Locale locale) {
    try {
        return ResourceBundle.getBundle(baseName, locale);
    } catch (NullPointerException e) {
        // Log the exception or handle it appropriately
        throw new IllegalArgumentException("baseName or locale cannot be null", e);
    } catch (MissingResourceException e) {
        // Log the exception or handle it appropriately
        throw new IllegalArgumentException("Resource bundle not found for baseName: " + baseName + " and locale: " + locale, e);
    }
}
